iv class="card-footer bg-white workspace-list-pagination"><div class="workspace-pagination-summary">Menampilkan <strong>{{ $items->firstItem() ?? 0 }}</strong>–<strong>{{ $items->lastItem() ?? 0 }}</strong> dari <strong>{{ $items->total() }}</strong> pengajuan</div>{{ $items->onEachSide(1)->links() }}</div></div>
<script>
document.addEventListener('DOMContentLoaded', () => {
    const drafts = [];
    @foreach($items->getCollection()->where('status', 'draft') as $draft)
        drafts.push({ edit: @json(route('workspace.hris.claims.edit', $draft)), delete: @json(route('workspace.hris.claims.destroy', $draft)) });
    @endforeach
    [...document.querySelectorAll('table tbody tr')].filter((row) => row.querySelector('td:nth-child(5)')?.textContent.trim().toLowerCase().includes('draft')).forEach((row, index) => {
        const action = row.lastElementChild;
        const draft = drafts[index];
        if (!action || !draft || action.dataset.draftActions) return;
        action.dataset.draftActions = 'true';
        action.insertAdjacentHTML('beforeend', `<a href="${draft.edit}" class="btn btn-sm btn-outline-primary">Edit draft</a><form method="POST" action="${draft.delete}" class="d-inline" data-confirm="Hapus draft reimbursement ini? Draft tidak dapat dipulihkan."><input type="hidden" name="_token" value="{{ csrf_token() }}"><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-outline-danger">Hapus draft</button></form>`);
    });
});
</script>
